window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["edcor-310-ch1"]={"schema":"precise-practice/1","bank_id":"edcor-310-ch1","book":"edcor-310","chapter":1,"title":"The Purpose of Education: The Grand Adventure","storage_version":1,"status":"draft","settings":{"goals":{"1":10,"2":5,"3":3}},"concepts":[{"id":"c1","number":1,"name":"The Grand Adventure of Becoming","activities":[{"id":"c1-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.1"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C1-QK-1","prompt":"A learner uses feedback from a hard attempt to improve on a new problem.","answer":0,"why":"This fits Antifragility: A system can become stronger through appropriately pitched challenge and feedback.","_v":"chapter1-tier1"},{"id":"E1-C1-QK-2","prompt":"A learner avoids every challenge and never changes strategy.","answer":1,"why":"This does not fit Antifragility: Fragility breaks under stress; resilience returns to its prior state.","_v":"chapter1-tier1"}]},{"id":"c1-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.1"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C1-SO-1","text":"A learner uses feedback from a hard attempt to improve on a new problem.","bin":0,"why":"The case illustrates Antifragility.","_v":"chapter1-tier1"},{"id":"E1-C1-SO-2","text":"A learner avoids every challenge and never changes strategy.","bin":1,"why":"The case conflicts with Antifragility.","_v":"chapter1-tier1"}]},{"id":"c1-match","type":"match","tier":1,"title":"Memory Match","targets":["1.1"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C1-MA-1","left":"Antifragility","right":"A system can become stronger through appropriately pitched challenge and feedback.","_v":"chapter1-tier1"},{"id":"E1-C1-MA-2","left":"Desirable difficulty","right":"Productive effort that strengthens later learning.","_v":"chapter1-tier1"}]},{"id":"c1-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.1"],"status":"draft","rounds":[{"id":"c1-detective-r1","term":"Antifragility","answers":[{"text":"A system can become stronger through appropriately pitched challenge and feedback. A learner uses feedback from a hard attempt to improve on a new problem.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"A system can become stronger through appropriately pitched challenge and feedback.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"A learner avoids every challenge and never changes strategy.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c1-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.1"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C1-CO-1","prompt":"Which situation better demonstrates Antifragility?","left":"A learner uses feedback from a hard attempt to improve on a new problem.","right":"A learner avoids every challenge and never changes strategy.","answer":0,"why":"The first situation matches A system can become stronger through appropriately pitched challenge and feedback.","_v":"chapter1-tier1"},{"id":"E1-C1-CO-2","prompt":"Which statement better reflects the chapter’s account of Antifragility?","left":"A system can become stronger through appropriately pitched challenge and feedback.","right":"Fragility breaks under stress; resilience returns to its prior state.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C1-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Antifragility.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c1-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.1"],"status":"draft","items":[{"id":"E1-C1-TBAP-1","prompt":"A student improves after attempting a difficult problem, reviewing feedback, and trying again. This is closest to:","options":["fragility","antifragility","passive resilience","avoidance"],"answer":1,"why":"The student uses stress and feedback to build greater capability.","_v":"edcor1"},{"id":"E1-C1-TBAP-2","prompt":"A course that never asks students to retrieve or apply ideas may produce:","options":["stronger transfer","fragile competence","automatic mastery","domain knowledge"],"answer":1,"why":"Competence that is never tested under challenge can fail when conditions change.","_v":"edcor1"}]},{"id":"c1-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.1"],"status":"draft","items":[{"id":"E1-C1-TBAP-3","prompt":"Which design is most likely to build antifragile skill?","options":["One high-stakes attempt","Repeated low-stakes attempts with feedback","No correction after errors","Only watching demonstrations"],"answer":1,"why":"Repeated attempts with feedback turn errors into information.","_v":"edcor1"},{"id":"E1-C1-TBAP-4","prompt":"A student recalls a definition but cannot use it in a new case. This is best described as:","options":["Robust transfer","Context-bound competence","Antifragile expertise","Mastery of application"],"answer":1,"why":"The student’s performance has not yet survived a change in context.","_v":"expanded-ch1"},{"id":"E1-C1-TBAP-5","prompt":"A task is so difficult that students cannot understand the goal or use feedback. It is most likely:","options":["Productive difficulty","Unproductive overload","Antifragile learning","Resilient transfer"],"answer":1,"why":"Challenge must be pitched so feedback can guide improvement.","_v":"expanded-ch1"},{"id":"E1-C1-TBAP-6","prompt":"Why does spaced retrieval often strengthen learning?","options":["It makes every question easy","It requires reconstruction after some forgetting","It eliminates the need for knowledge","It measures personality"],"answer":1,"why":"Retrieval after time has passed strengthens access and reveals what needs more work.","_v":"expanded-ch1"},{"id":"E1-C1-TBAP-7","prompt":"Which student response most clearly shows antifragility?","options":["The student avoids every difficult problem","The student uses an error to revise a strategy and improves on a new problem","The student repeats the same answer","The student performs only when prompted"],"answer":1,"why":"The learner becomes more capable through feedback from challenge.","_v":"expanded-ch1"}]},{"id":"c1-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.1"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C1-TI-1","title":"Explain Antifragility 1","prompt":"Complete the explanation.","correct":["Challenge reveals what can be improved","and feedback helps the learner adapt"],"wrong":["Challenge always guarantees success","and support makes learning impossible"],"why":"A system can become stronger through appropriately pitched challenge and feedback.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C1-TI-2","title":"Explain Antifragility 2","prompt":"Complete the explanation.","correct":["Challenge reveals what can be improved","and feedback helps the learner adapt"],"wrong":["Challenge always guarantees success","and support makes learning impossible"],"why":"A system can become stronger through appropriately pitched challenge and feedback.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C1-TI-3","title":"Explain Antifragility 3","prompt":"Complete the explanation.","correct":["Challenge reveals what can be improved","and feedback helps the learner adapt"],"wrong":["Challenge always guarantees success","and support makes learning impossible"],"why":"A system can become stronger through appropriately pitched challenge and feedback.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c1-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.1"],"status":"draft","items":[{"id":"E1-C1-AP-1","prompt":"A learner performs well on familiar examples but fails when the context changes. The best diagnosis is:","options":["antifragile transfer","fragile or context-bound competence","mastery of the domain","productive failure"],"answer":1,"why":"Performance that collapses under changed conditions is not robust competence.","_v":"edcor1"},{"id":"E1-C1-AP-2","prompt":"Why can carefully chosen difficulty improve learning?","options":["Difficulty guarantees success","It creates information for adaptation","It removes the need for knowledge","It makes every task fair"],"answer":1,"why":"Challenge exposes what needs to change and supports adaptation when paired with feedback.","_v":"edcor1"},{"id":"E1-C1-AP-3","prompt":"Which claim best captures the chapter’s view of education?","options":["Education should eliminate uncertainty","Education should help people become more capable through challenge","Education is only content delivery","Education should measure comfort"],"answer":1,"why":"The chapter treats growth through challenge as central to becoming.","_v":"edcor1"},{"id":"E1-C1-AP-4","prompt":"A teacher says, “If students struggle, the assignment is automatically rigorous.” What is the best response?","options":["Yes, struggle always proves rigor","No; rigor requires meaningful cognitive demand and usable support","Yes, because content knowledge is irrelevant","No; rigorous work must never be difficult"],"answer":1,"why":"Difficulty alone is not rigor; the challenge must require meaningful thinking and support learning.","_v":"expanded-ch1"},{"id":"E1-C1-AP-5","prompt":"Which course design best combines antifragility and mastery?","options":["One irreversible exam","Repeated challenging attempts with feedback and advancement after demonstrated learning","Only easy practice","A final grade based on speed"],"answer":1,"why":"Students gain capability through challenge while mastery keeps the learning target clear.","_v":"expanded-ch1"}]}]},{"id":"c2","number":2,"name":"Bloom's Taxonomy","activities":[{"id":"c2-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.2"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C2-QK-1","prompt":"A student compares evidence and defends which explanation is best supported.","answer":0,"why":"This fits Bloom’s taxonomy: A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","_v":"chapter1-tier1"},{"id":"E1-C2-QK-2","prompt":"A teacher labels a student permanently as a low-level thinker.","answer":1,"why":"This does not fit Bloom’s taxonomy: The taxonomy describes objectives and tasks; it is not a permanent ranking of students.","_v":"chapter1-tier1"}]},{"id":"c2-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.2"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C2-SO-1","text":"A student compares evidence and defends which explanation is best supported.","bin":0,"why":"The case illustrates Bloom’s taxonomy.","_v":"chapter1-tier1"},{"id":"E1-C2-SO-2","text":"A teacher labels a student permanently as a low-level thinker.","bin":1,"why":"The case conflicts with Bloom’s taxonomy.","_v":"chapter1-tier1"}]},{"id":"c2-match","type":"match","tier":1,"title":"Memory Match","targets":["1.2"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C2-MA-1","left":"Bloom’s taxonomy","right":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","_v":"chapter1-tier1"},{"id":"E1-C2-MA-2","left":"Affective domain","right":"The domain of values, attitudes, and character.","_v":"chapter1-tier1"}]},{"id":"c2-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.2"],"status":"draft","rounds":[{"id":"c2-detective-r1","term":"Bloom’s taxonomy","answers":[{"text":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains. A student compares evidence and defends which explanation is best supported.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"A teacher labels a student permanently as a low-level thinker.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c2-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.2"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C2-CO-1","prompt":"Which situation better demonstrates Bloom’s taxonomy?","left":"A student compares evidence and defends which explanation is best supported.","right":"A teacher labels a student permanently as a low-level thinker.","answer":0,"why":"The first situation matches A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","_v":"chapter1-tier1"},{"id":"E1-C2-CO-2","prompt":"Which statement better reflects the chapter’s account of Bloom’s taxonomy?","left":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","right":"The taxonomy describes objectives and tasks; it is not a permanent ranking of students.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C2-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Bloom’s taxonomy.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c2-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.2"],"status":"draft","items":[{"id":"E1-C2-TBAP-1","prompt":"A student compares two arguments and identifies which evidence supports each claim. That task is mainly:","options":["Remember","Understand","Analyze","Create"],"answer":2,"why":"Comparing claims and evidence requires analysis of relationships.","_v":"edcor1"},{"id":"E1-C2-TBAP-2","prompt":"A student explains a concept in their own words without using it in a case. This is mainly:","options":["Understand","Apply","Evaluate","Create"],"answer":0,"why":"Explaining meaning is understanding; use in a case would be applying.","_v":"edcor1"}]},{"id":"c2-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.2"],"status":"draft","items":[{"id":"E1-C2-TBAP-3","prompt":"Which prompt most clearly asks students to evaluate?","options":["List three terms","Explain the diagram","Use the rule on a case","Defend which policy is best with evidence"],"answer":3,"why":"Evaluation requires a reasoned judgment supported by criteria or evidence.","_v":"edcor1"},{"id":"E1-C2-TBAP-4","prompt":"A student breaks an argument into claims and evidence, then identifies how the parts relate. This is:","options":["Remembering","Analyzing","Creating","Psychomotor practice"],"answer":1,"why":"Analyzing examines parts and relationships.","_v":"expanded-ch1"},{"id":"E1-C2-TBAP-5","prompt":"A student chooses the best-supported explanation using explicit criteria. This is:","options":["Understanding","Applying","Evaluating","Remembering"],"answer":2,"why":"Evaluation involves a judgment using criteria or evidence.","_v":"expanded-ch1"},{"id":"E1-C2-TBAP-6","prompt":"A teacher asks students to produce a new model that explains a problem. The highest demand is:","options":["Remember","Understand","Analyze","Create"],"answer":3,"why":"Producing a new model is creation.","_v":"expanded-ch1"},{"id":"E1-C2-TBAP-7","prompt":"A teacher asks students to compare two explanations, judge which is better supported, and defend the judgment. Which cognitive demand is most central?","options":["Remember","Analyze and evaluate","Understand only","Psychomotor practice"],"answer":1,"why":"Comparing evidence and defending a judgment require analysis and evaluation.","_v":"assessment-edcor1"}]},{"id":"c2-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.2"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C2-TI-1","title":"Explain Bloom’s taxonomy 1","prompt":"Complete the explanation.","correct":["Bloom’s levels clarify the demand of a task","but they do not rank a person’s worth"],"wrong":["Bloom’s levels replace domain knowledge","and guarantee automatic transfer"],"why":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C2-TI-2","title":"Explain Bloom’s taxonomy 2","prompt":"Complete the explanation.","correct":["Bloom’s levels clarify the demand of a task","but they do not rank a person’s worth"],"wrong":["Bloom’s levels replace domain knowledge","and guarantee automatic transfer"],"why":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C2-TI-3","title":"Explain Bloom’s taxonomy 3","prompt":"Complete the explanation.","correct":["Bloom’s levels clarify the demand of a task","but they do not rank a person’s worth"],"wrong":["Bloom’s levels replace domain knowledge","and guarantee automatic transfer"],"why":"A framework that classifies cognitive demand from Remember through Create and also distinguishes affective and psychomotor domains.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c2-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.2"],"status":"draft","items":[{"id":"E1-C2-AP-1","prompt":"Why does a taxonomy help an instructor?","options":["It proves a student’s character","It clarifies the cognitive demand of a task","It replaces domain knowledge","It guarantees transfer"],"answer":1,"why":"A taxonomy makes the intended level of thinking more explicit.","_v":"edcor1"},{"id":"E1-C2-AP-2","prompt":"A task asks students to design a lesson that solves a problem and justify its choices. Its highest demand is:","options":["Remember","Apply","Evaluate","Create"],"answer":3,"why":"Designing a new solution is creating, with evaluation embedded in the justification.","_v":"edcor1"},{"id":"E1-C2-AP-3","prompt":"What is a common misuse of Bloom’s taxonomy?","options":["Using it to clarify objectives","Treating the levels as a simple measure of human worth","Writing prompts at different cognitive demands","Connecting tasks to outcomes"],"answer":1,"why":"Bloom’s framework classifies objectives; it does not rank people.","_v":"edcor1"},{"id":"E1-C2-AP-4","prompt":"A course uses Bloom’s levels to label students as high or low thinkers. What is wrong with that use?","options":["The taxonomy classifies task demands, not a permanent worth or ability ranking","Bloom has no cognitive levels","Students should never analyze","Only affective outcomes matter"],"answer":0,"why":"Bloom’s taxonomy describes objectives and tasks; it is not a fixed ranking of people.","_v":"expanded-ch1"},{"id":"E1-C2-AP-5","prompt":"A lesson teaches students to value intellectual honesty, practice evidence-based reasoning, and design a research study. Which statement is strongest?","options":["It addresses affective, cognitive, and possibly psychomotor dimensions rather than cognition alone","It is only Remember-level work","It cannot be rigorous because values are involved","It replaces knowledge with emotion"],"answer":0,"why":"The lesson combines values, intellectual reasoning, and practice in a broader educational purpose.","_v":"expanded-ch1"}]}]},{"id":"c3","number":3,"name":"The Tragedy of Benjamin Bloom","activities":[{"id":"c3-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.3"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C3-QK-1","prompt":"A student studies a targeted correction, retakes the assessment, and advances after meeting the target.","answer":0,"why":"This fits Mastery learning: Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","_v":"chapter1-tier1"},{"id":"E1-C3-QK-2","prompt":"Students move forward only because the calendar says it is time.","answer":1,"why":"This does not fit Mastery learning: Mastery varies time and support while keeping the learning target meaningful.","_v":"chapter1-tier1"}]},{"id":"c3-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.3"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C3-SO-1","text":"A student studies a targeted correction, retakes the assessment, and advances after meeting the target.","bin":0,"why":"The case illustrates Mastery learning.","_v":"chapter1-tier1"},{"id":"E1-C3-SO-2","text":"Students move forward only because the calendar says it is time.","bin":1,"why":"The case conflicts with Mastery learning.","_v":"chapter1-tier1"}]},{"id":"c3-match","type":"match","tier":1,"title":"Memory Match","targets":["1.3"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C3-MA-1","left":"Mastery learning","right":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","_v":"chapter1-tier1"},{"id":"E1-C3-MA-2","left":"Two-sigma problem","right":"Bloom’s finding that tutoring or mastery conditions can produce substantially higher performance.","_v":"chapter1-tier1"}]},{"id":"c3-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.3"],"status":"draft","rounds":[{"id":"c3-detective-r1","term":"Mastery learning","answers":[{"text":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing. A student studies a targeted correction, retakes the assessment, and advances after meeting the target.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"Students move forward only because the calendar says it is time.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c3-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.3"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C3-CO-1","prompt":"Which situation better demonstrates Mastery learning?","left":"A student studies a targeted correction, retakes the assessment, and advances after meeting the target.","right":"Students move forward only because the calendar says it is time.","answer":0,"why":"The first situation matches Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","_v":"chapter1-tier1"},{"id":"E1-C3-CO-2","prompt":"Which statement better reflects the chapter’s account of Mastery learning?","left":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","right":"Mastery varies time and support while keeping the learning target meaningful.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C3-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Mastery learning.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c3-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.3"],"status":"draft","items":[{"id":"E1-C3-TBAP-1","prompt":"A student scores below a threshold, studies a targeted correction, retakes, and then advances. This is:","options":["mastery learning","ranking by first attempt","lowered expectations","unstructured practice"],"answer":0,"why":"The sequence uses feedback and corrective work before advancement.","_v":"edcor1"},{"id":"E1-C3-TBAP-2","prompt":"A school lets students retake tests but averages all attempts without additional instruction. What is missing?","options":["A higher grade","Corrective learning before the next attempt","A calendar","A final exam"],"answer":1,"why":"Retakes become mastery-oriented when they follow feedback and corrective work.","_v":"edcor1"}]},{"id":"c3-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.3"],"status":"draft","items":[{"id":"E1-C3-TBAP-3","prompt":"Why can individualized tutoring outperform ordinary instruction?","options":["It removes all challenge","It provides immediate adaptation and feedback","It eliminates subject knowledge","It guarantees identical outcomes"],"answer":1,"why":"Tutoring can respond to a learner’s current understanding in real time.","_v":"edcor1"},{"id":"E1-C3-TBAP-4","prompt":"A student misses a target, receives a targeted explanation, practices the gap, and retakes the assessment. The retake is most useful because it:","options":["Shows whether corrective learning produced mastery","Erases the original learning goal","Rewards speed","Replaces instruction"],"answer":0,"why":"The second opportunity tests learning after correction.","_v":"expanded-ch1"},{"id":"E1-C3-TBAP-5","prompt":"What should remain constant when mastery learning varies the amount of time students receive?","options":["The learning target","The number of mistakes allowed by the calendar","The first score","The amount of homework"],"answer":0,"why":"Mastery varies support and time while keeping the target meaningful.","_v":"expanded-ch1"},{"id":"E1-C3-TBAP-6","prompt":"Why can tutoring produce large gains?","options":["It can adapt explanation, feedback, and practice to the learner’s current need","It eliminates all effort","It guarantees identical personalities","It avoids assessment"],"answer":0,"why":"Responsive instruction makes correction more precise.","_v":"expanded-ch1"},{"id":"E1-C3-TBAP-7","prompt":"A school allows unlimited retakes but gives no feedback or corrective work. What is missing?","options":["A mastery process","A final exam","A higher first score","A harder textbook"],"answer":0,"why":"Retakes alone do not create mastery without learning support.","_v":"expanded-ch1"}]},{"id":"c3-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.3"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C3-TI-1","title":"Explain Mastery learning 1","prompt":"Complete the explanation.","correct":["Mastery keeps the target clear","while varying time and corrective support"],"wrong":["Mastery lowers every target","and treats the first score as final"],"why":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C3-TI-2","title":"Explain Mastery learning 2","prompt":"Complete the explanation.","correct":["Mastery keeps the target clear","while varying time and corrective support"],"wrong":["Mastery lowers every target","and treats the first score as final"],"why":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C3-TI-3","title":"Explain Mastery learning 3","prompt":"Complete the explanation.","correct":["Mastery keeps the target clear","while varying time and corrective support"],"wrong":["Mastery lowers every target","and treats the first score as final"],"why":"Students receive feedback, corrective instruction, and enough opportunity to meet a clear target before advancing.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c3-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.3"],"status":"draft","items":[{"id":"E1-C3-AP-1","prompt":"The chapter’s tragedy is that Bloom’s work was often reduced to:","options":["A richer theory of mastery","A checklist or hierarchy detached from its instructional purpose","A tutoring program","A critique of feedback"],"answer":1,"why":"The framework’s practical vision was narrowed into a label system.","_v":"edcor1"},{"id":"E1-C3-AP-2","prompt":"Which policy best preserves Bloom’s central insight while keeping standards high?","options":["Lower the standard for struggling students","Keep the goal, vary time and support","Use one attempt to sort students","Avoid feedback to protect confidence"],"answer":1,"why":"Mastery keeps the destination stable while adapting support and time.","_v":"edcor1"},{"id":"E1-C3-AP-3","prompt":"What would be the strongest evidence that a mastery intervention worked?","options":["Students felt busy","Students eventually met the target after corrective instruction","The first test was difficult","Scores were averaged"],"answer":1,"why":"The key outcome is demonstrated learning after support, not initial speed.","_v":"edcor1"},{"id":"E1-C3-AP-4","prompt":"Which criticism of a purely time-based course follows from mastery learning?","options":["Students may advance before they have learned the target","Students receive too much corrective feedback","The target is always too clear","Tutoring cannot help"],"answer":0,"why":"Calendar-based progression can separate advancement from demonstrated learning.","_v":"expanded-ch1"},{"id":"E1-C3-AP-5","prompt":"Which policy best captures Bloom’s central instructional insight?","options":["Keep high learning targets while varying time, feedback, and corrective support","Lower targets for students who need more time","Use one score to predict potential","Remove challenging content"],"answer":0,"why":"The standard stays meaningful while instruction responds to learner needs.","_v":"expanded-ch1"}]}]},{"id":"c4","number":4,"name":"High Expectations","activities":[{"id":"c4-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.4"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C4-QK-1","prompt":"A teacher keeps a demanding goal and gives a student modeling, wait time, and specific feedback.","answer":0,"why":"This fits Pygmalion effect: Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","_v":"chapter1-tier1"},{"id":"E1-C4-QK-2","prompt":"A teacher lowers the learning target because struggle is treated as proof of inability.","answer":1,"why":"This does not fit Pygmalion effect: High expectations require support; belief alone is not a teaching strategy.","_v":"chapter1-tier1"}]},{"id":"c4-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.4"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C4-SO-1","text":"A teacher keeps a demanding goal and gives a student modeling, wait time, and specific feedback.","bin":0,"why":"The case illustrates Pygmalion effect.","_v":"chapter1-tier1"},{"id":"E1-C4-SO-2","text":"A teacher lowers the learning target because struggle is treated as proof of inability.","bin":1,"why":"The case conflicts with Pygmalion effect.","_v":"chapter1-tier1"}]},{"id":"c4-match","type":"match","tier":1,"title":"Memory Match","targets":["1.4"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C4-MA-1","left":"Pygmalion effect","right":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","_v":"chapter1-tier1"},{"id":"E1-C4-MA-2","left":"High expectations","right":"Maintaining meaningful goals while providing a path and support for students to reach them.","_v":"chapter1-tier1"}]},{"id":"c4-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.4"],"status":"draft","rounds":[{"id":"c4-detective-r1","term":"Pygmalion effect","answers":[{"text":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support. A teacher keeps a demanding goal and gives a student modeling, wait time, and specific feedback.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"A teacher lowers the learning target because struggle is treated as proof of inability.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c4-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.4"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C4-CO-1","prompt":"Which situation better demonstrates Pygmalion effect?","left":"A teacher keeps a demanding goal and gives a student modeling, wait time, and specific feedback.","right":"A teacher lowers the learning target because struggle is treated as proof of inability.","answer":0,"why":"The first situation matches Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","_v":"chapter1-tier1"},{"id":"E1-C4-CO-2","prompt":"Which statement better reflects the chapter’s account of Pygmalion effect?","left":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","right":"High expectations require support; belief alone is not a teaching strategy.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C4-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Pygmalion effect.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c4-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.4"],"status":"draft","items":[{"id":"E1-C4-TBAP-1","prompt":"A teacher assumes a student cannot handle complex work and gives only simple worksheets. This illustrates:","options":["a self-fulfilling expectation","mastery learning","domain transfer","productive failure"],"answer":0,"why":"The expectation changes the opportunities offered, which can affect performance.","_v":"edcor1"},{"id":"E1-C4-TBAP-2","prompt":"Which response best reflects high expectations?","options":["Keep the goal and add scaffolding","Remove the difficult goal","Give praise without instruction","Wait for students to teach themselves"],"answer":0,"why":"Scaffolding supports students without abandoning the demanding target.","_v":"edcor1"}]},{"id":"c4-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.4"],"status":"draft","items":[{"id":"E1-C4-TBAP-3","prompt":"If a student is struggling, the chapter recommends first asking:","options":["How can the task be made easier forever?","What support and instruction would help the student reach the goal?","Should the student be excluded?","Can the standard be removed?"],"answer":1,"why":"The focus is on support and instruction rather than a fixed judgment.","_v":"edcor1"},{"id":"E1-C4-TBAP-4","prompt":"A teacher believes a student can reason well and gives the student time to explain, feedback, and challenging examples. This illustrates:","options":["An expectation operating through instructional behavior","A Type II error","Psychomotor learning","Calendar progression"],"answer":0,"why":"Expectations can influence concrete interactions and opportunities.","_v":"expanded-ch1"},{"id":"E1-C4-TBAP-5","prompt":"Why are high expectations not the same as simply being optimistic?","options":["They require instruction and support that help students reach the goal","They eliminate the need for standards","They guarantee equal scores","They avoid difficult feedback"],"answer":0,"why":"Belief without effective teaching does not make a demanding target reachable.","_v":"expanded-ch1"},{"id":"E1-C4-TBAP-6","prompt":"Which response best balances accommodation and expectations?","options":["Provide needed support while preserving meaningful learning goals","Remove the learning goal entirely","Give only easier work forever","Treat accommodation as proof of inability"],"answer":0,"why":"Support should improve access without abandoning the target.","_v":"expanded-ch1"},{"id":"E1-C4-TBAP-7","prompt":"If students are given challenging work but no modeling, feedback, or time, the main problem is:","options":["The pathway to the expectation is missing","The standard is necessarily too low","The class is automatically rigorous","The Pygmalion effect cannot exist"],"answer":0,"why":"Students need usable instructional support to meet high expectations.","_v":"expanded-ch1"}]},{"id":"c4-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.4"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C4-TI-1","title":"Explain Pygmalion effect 1","prompt":"Complete the explanation.","correct":["Expectations can shape the opportunities students receive","so high standards should be paired with useful support"],"wrong":["Expectations determine every outcome","so instruction and feedback are unnecessary"],"why":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C4-TI-2","title":"Explain Pygmalion effect 2","prompt":"Complete the explanation.","correct":["Expectations can shape the opportunities students receive","so high standards should be paired with useful support"],"wrong":["Expectations determine every outcome","so instruction and feedback are unnecessary"],"why":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C4-TI-3","title":"Explain Pygmalion effect 3","prompt":"Complete the explanation.","correct":["Expectations can shape the opportunities students receive","so high standards should be paired with useful support"],"wrong":["Expectations determine every outcome","so instruction and feedback are unnecessary"],"why":"Teacher expectations can influence student performance through differences in attention, feedback, opportunity, and support.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c4-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.4"],"status":"draft","items":[{"id":"E1-C4-AP-1","prompt":"Why are high expectations a moral commitment rather than just a motivational trick?","options":["They determine who receives meaningful opportunities to learn","They make all students identical","They remove the need for teaching","They guarantee equal scores"],"answer":0,"why":"Expectations influence the seriousness and quality of opportunities students receive.","_v":"edcor1"},{"id":"E1-C4-AP-2","prompt":"A teacher believes in students but provides no models, feedback, or time. What is incomplete?","options":["Belief alone is enough","High expectations require instructional support","Rigor is impossible","Standards should be lowered"],"answer":1,"why":"Hope without useful teaching does not create access to the target.","_v":"edcor1"},{"id":"E1-C4-AP-3","prompt":"Which pattern best distinguishes rigor from unreasonable demand?","options":["Demand without support","A challenging goal with instruction, feedback, and revision","Easy tasks with high praise","A single timed test"],"answer":1,"why":"Rigor pairs meaningful challenge with a path to improvement.","_v":"edcor1"},{"id":"E1-C4-AP-4","prompt":"Which conclusion about Pygmalion effects is most defensible?","options":["Expectations can matter through behavior, but they do not explain every outcome or replace good instruction","Believing harder guarantees every result","Teacher expectations never affect opportunity","All differences are caused by expectations"],"answer":0,"why":"The effect is a mechanism of influence, not a complete explanation of achievement.","_v":"expanded-ch1"},{"id":"E1-C4-AP-5","prompt":"A teacher wants to avoid both low expectations and empty praise. Which practice is best?","options":["Set a demanding target, provide evidence-based support, and give specific feedback","Praise every answer regardless of quality","Remove difficult tasks","Use the same support regardless of need"],"answer":0,"why":"Calibrated support preserves standards while giving students information for improvement.","_v":"expanded-ch1"}]}]},{"id":"c5","number":5,"name":"Domain-Specific Knowledge","activities":[{"id":"c5-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.5"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C5-QK-1","prompt":"A student uses historical concepts and evidence to evaluate a new historical source.","answer":0,"why":"This fits Domain-specific knowledge: Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","_v":"chapter1-tier1"},{"id":"E1-C5-QK-2","prompt":"A generic thinking slogan lets a student analyze any unfamiliar subject without background knowledge.","answer":1,"why":"This does not fit Domain-specific knowledge: Critical thinking is not a context-free shortcut that transfers automatically everywhere.","_v":"chapter1-tier1"}]},{"id":"c5-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.5"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C5-SO-1","text":"A student uses historical concepts and evidence to evaluate a new historical source.","bin":0,"why":"The case illustrates Domain-specific knowledge.","_v":"chapter1-tier1"},{"id":"E1-C5-SO-2","text":"A generic thinking slogan lets a student analyze any unfamiliar subject without background knowledge.","bin":1,"why":"The case conflicts with Domain-specific knowledge.","_v":"chapter1-tier1"}]},{"id":"c5-match","type":"match","tier":1,"title":"Memory Match","targets":["1.5"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C5-MA-1","left":"Domain-specific knowledge","right":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","_v":"chapter1-tier1"},{"id":"E1-C5-MA-2","left":"Knowledge-based reasoning","right":"Using organized domain knowledge to interpret evidence and reach a justified conclusion.","_v":"chapter1-tier1"}]},{"id":"c5-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.5"],"status":"draft","rounds":[{"id":"c5-detective-r1","term":"Domain-specific knowledge","answers":[{"text":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs. A student uses historical concepts and evidence to evaluate a new historical source.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"A generic thinking slogan lets a student analyze any unfamiliar subject without background knowledge.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c5-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.5"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C5-CO-1","prompt":"Which situation better demonstrates Domain-specific knowledge?","left":"A student uses historical concepts and evidence to evaluate a new historical source.","right":"A generic thinking slogan lets a student analyze any unfamiliar subject without background knowledge.","answer":0,"why":"The first situation matches Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","_v":"chapter1-tier1"},{"id":"E1-C5-CO-2","prompt":"Which statement better reflects the chapter’s account of Domain-specific knowledge?","left":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","right":"Critical thinking is not a context-free shortcut that transfers automatically everywhere.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C5-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Domain-specific knowledge.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c5-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.5"],"status":"draft","items":[{"id":"E1-C5-TBAP-1","prompt":"A student can identify bias in a familiar history topic but not in an unfamiliar scientific article. This suggests:","options":["thinking transfers automatically","critical thinking is partly domain-specific","knowledge blocks reasoning","the student learned nothing"],"answer":1,"why":"Reasoning performance can change when the relevant knowledge base changes.","_v":"edcor1"},{"id":"E1-C5-TBAP-2","prompt":"Which lesson best supports transfer?","options":["Teach a generic thinking slogan","Build knowledge, then practice reasoning across related cases","Skip content and teach only debate","Use one example once"],"answer":1,"why":"Transfer improves when students have knowledge and practice applying it in varied cases.","_v":"edcor1"}]},{"id":"c5-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.5"],"status":"draft","items":[{"id":"E1-C5-TBAP-3","prompt":"Why might a class discussion fail to produce deep analysis?","options":["Students have too much knowledge","Students lack the background needed to evaluate the evidence","Discussion always lowers rigor","Facts make thinking impossible"],"answer":1,"why":"Without relevant knowledge, analysis can become shallow or unsupported.","_v":"edcor1"},{"id":"E1-C5-TBAP-4","prompt":"A student can identify bias in a familiar history unit but not an unfamiliar science article. The best explanation is:","options":["The relevant knowledge base differs across domains","The student has no critical-thinking ability","History requires no evidence","Science cannot be analyzed"],"answer":0,"why":"Reasoning can depend on knowledge specific to the domain.","_v":"expanded-ch1"},{"id":"E1-C5-TBAP-5","prompt":"Which sequence is most likely to support transfer?","options":["Build domain knowledge, model reasoning, then practice across related cases","Teach a generic slogan once","Start with an unfamiliar case and provide no background","Assess recall only"],"answer":0,"why":"Knowledge and guided variation create a foundation for transfer.","_v":"expanded-ch1"},{"id":"E1-C5-TBAP-6","prompt":"Why can a discussion remain shallow even when students are asked to think critically?","options":["Students may lack the background knowledge needed to evaluate the claims","Discussion always prevents reasoning","Facts make thinking impossible","The teacher used too many examples"],"answer":0,"why":"Without relevant knowledge, students may have no evidence base for analysis.","_v":"expanded-ch1"},{"id":"E1-C5-TBAP-7","prompt":"Which assessment best tests whether students can reason with domain knowledge?","options":["A new case requiring evidence and a justified conclusion","Copying definitions","Choosing the longest answer","Recalling a single date"],"answer":0,"why":"A new case tests use of knowledge in reasoning.","_v":"expanded-ch1"}]},{"id":"c5-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.5"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C5-TI-1","title":"Explain Domain-specific knowledge 1","prompt":"Complete the explanation.","correct":["Domain knowledge gives reasoning material to work with","so transfer requires practice in meaningful contexts"],"wrong":["Generic routines replace content knowledge","so examples and evidence are unnecessary"],"why":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C5-TI-2","title":"Explain Domain-specific knowledge 2","prompt":"Complete the explanation.","correct":["Domain knowledge gives reasoning material to work with","so transfer requires practice in meaningful contexts"],"wrong":["Generic routines replace content knowledge","so examples and evidence are unnecessary"],"why":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C5-TI-3","title":"Explain Domain-specific knowledge 3","prompt":"Complete the explanation.","correct":["Domain knowledge gives reasoning material to work with","so transfer requires practice in meaningful contexts"],"wrong":["Generic routines replace content knowledge","so examples and evidence are unnecessary"],"why":"Good reasoning depends partly on rich knowledge of the subject in which the reasoning occurs.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c5-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.5"],"status":"draft","items":[{"id":"E1-C5-AP-1","prompt":"The chapter’s prescription for critical thinking is best summarized as:","options":["Teach more domain knowledge and then use it for reasoning","Choose skills instead of content","Avoid factual recall","Assume transfer"],"answer":0,"why":"Domain knowledge is a foundation on which higher-order reasoning can operate.","_v":"edcor1"},{"id":"E1-C5-AP-2","prompt":"A student memorizes vocabulary but cannot explain a new example. What is most needed?","options":["More isolated words","Guided application in the domain","Less practice","A lower standard"],"answer":1,"why":"Application connects knowledge to new cases and reveals what the learner understands.","_v":"edcor1"},{"id":"E1-C5-AP-3","prompt":"Which assessment best tests knowledge-based reasoning?","options":["A list of terms only","A new case requiring evidence from the domain","A popularity vote","A speed contest"],"answer":1,"why":"A new case tests whether students can use domain knowledge to reason.","_v":"edcor1"},{"id":"E1-C5-AP-4","prompt":"A team teaches generic critical-thinking routines but little subject matter. What is the strongest concern?","options":["The routines may not transfer because reasoning is tied to domain knowledge","Students will automatically become experts","Facts are unnecessary for analysis","Transfer is guaranteed by repetition"],"answer":0,"why":"Willingham’s argument predicts limited transfer without a rich knowledge base.","_v":"expanded-ch1"},{"id":"E1-C5-AP-5","prompt":"Which claim best reflects the chapter’s view of expertise?","options":["Expert reasoning is supported by organized knowledge, not just a general thinking habit","Expertise is only confidence","Experts never use facts","All reasoning is context-free"],"answer":0,"why":"Domain knowledge makes complex reasoning faster and more accurate.","_v":"expanded-ch1"}]}]},{"id":"c6","number":6,"name":"Teleology and Rigor","activities":[{"id":"c6-quick","type":"quick","tier":1,"title":"Quick classify","targets":["1.6"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Fits the concept","Does not fit the concept"],"round_size":2,"items":[{"id":"E1-C6-QK-1","prompt":"A short unfamiliar case asks students to choose a principle and defend the decision with evidence.","answer":0,"why":"This fits Telos and rigor: Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","_v":"chapter1-tier1"},{"id":"E1-C6-QK-2","prompt":"A long worksheet is called rigorous only because it contains more pages.","answer":1,"why":"This does not fit Telos and rigor: A longer or harder assignment is not automatically more rigorous.","_v":"chapter1-tier1"}]},{"id":"c6-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["1.6"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Fits the concept","Does not fit the concept"],"round_size":2,"cards":[{"id":"E1-C6-SO-1","text":"A short unfamiliar case asks students to choose a principle and defend the decision with evidence.","bin":0,"why":"The case illustrates Telos and rigor.","_v":"chapter1-tier1"},{"id":"E1-C6-SO-2","text":"A long worksheet is called rigorous only because it contains more pages.","bin":1,"why":"The case conflicts with Telos and rigor.","_v":"chapter1-tier1"}]},{"id":"c6-match","type":"match","tier":1,"title":"Memory Match","targets":["1.6"],"status":"draft","board_size":2,"pairs":[{"id":"E1-C6-MA-1","left":"Telos and rigor","right":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","_v":"chapter1-tier1"},{"id":"E1-C6-MA-2","left":"Person-formation","right":"Education’s purpose includes shaping judgment, character, and how students respond—not only recall.","_v":"chapter1-tier1"}]},{"id":"c6-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["1.6"],"status":"draft","rounds":[{"id":"c6-detective-r1","term":"Telos and rigor","answers":[{"text":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork. A short unfamiliar case asks students to choose a principle and defend the decision with evidence.","grade":"A","why":"This answer gives the definition and applies it to a fitting example."},{"text":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","grade":"A-","why":"This is accurate but does not yet demonstrate the concept in a case."},{"text":"A long worksheet is called rigorous only because it contains more pages.","grade":"F","why":"This describes the misconception or the opposite of the concept."}],"_v":"chapter1-tier1"}]},{"id":"c6-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["1.6"],"status":"draft","instructions":"Choose the situation that best fits the concept.","labels":["A","B"],"round_size":3,"items":[{"id":"E1-C6-CO-1","prompt":"Which situation better demonstrates Telos and rigor?","left":"A short unfamiliar case asks students to choose a principle and defend the decision with evidence.","right":"A long worksheet is called rigorous only because it contains more pages.","answer":0,"why":"The first situation matches Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","_v":"chapter1-tier1"},{"id":"E1-C6-CO-2","prompt":"Which statement better reflects the chapter’s account of Telos and rigor?","left":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","right":"A longer or harder assignment is not automatically more rigorous.","answer":0,"why":"The first statement gives the concept’s positive definition.","_v":"chapter1-tier1"},{"id":"E1-C6-CO-3","prompt":"Which design better supports the concept?","left":"Use a clear target, meaningful challenge, and feedback related to Telos and rigor.","right":"Use a one-time task with no feedback and label the first result permanent.","answer":0,"why":"Practice with feedback supports understanding and application.","_v":"chapter1-tier1"}]},{"id":"c6-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["1.6"],"status":"draft","items":[{"id":"E1-C6-TBAP-1","prompt":"A teacher raises the reading level but removes the need to reason. The change is:","options":["necessarily more rigorous","harder but not necessarily more rigorous","mastery learning","teleological"],"answer":1,"why":"Difficulty without meaningful cognitive demand is not rigor.","_v":"edcor1"},{"id":"E1-C6-TBAP-2","prompt":"If the telos of education is human flourishing, an assessment should primarily ask whether students:","options":["can sort themselves by speed","are becoming more capable of understanding and acting well","avoid all mistakes","memorize without purpose"],"answer":1,"why":"Purpose should guide what the assessment values.","_v":"edcor1"}]},{"id":"c6-applied","type":"choice","tier":2,"title":"Applied cases","targets":["1.6"],"status":"draft","items":[{"id":"E1-C6-TBAP-3","prompt":"Which task most clearly combines rigor with purpose?","options":["Defend a claim with domain evidence and explain its consequences","Copy a definition ten times","Complete a longer worksheet","Guess the teacher’s preference"],"answer":0,"why":"The task requires evidence, reasoning, and attention to consequences.","_v":"edcor1"},{"id":"E1-C6-TBAP-4","prompt":"Which assignment is more rigorous?","options":["A longer worksheet repeating a demonstrated method","A shorter set of unfamiliar cases requiring justified choices","A larger vocabulary list","A faster recall quiz"],"answer":1,"why":"Rigor concerns cognitive demand, especially transfer and justification.","_v":"expanded-ch1"},{"id":"E1-C6-TBAP-5","prompt":"Why does telos matter for assessment?","options":["Purpose determines which forms of growth count as success","Purpose makes evidence unnecessary","Purpose requires every student to learn identically","Purpose is unrelated to tasks"],"answer":0,"why":"Assessments should reflect what education is for.","_v":"expanded-ch1"},{"id":"E1-C6-TBAP-6","prompt":"A school claims to develop independent thinkers but rewards only rapid recall. This is primarily:","options":["A mismatch between stated purpose and practice","Evidence of mastery learning","Proof of high rigor","A psychomotor goal"],"answer":0,"why":"The incentives do not match the stated telos.","_v":"expanded-ch1"},{"id":"E1-C6-TBAP-7","prompt":"A challenging task with clear evidence, feedback, and revision is more rigorous than a long task because it:","options":["Requires meaningful thinking rather than merely more work","Always takes less time","Uses fewer words","Avoids content knowledge"],"answer":0,"why":"Cognitive demand and reasoning matter more than volume.","_v":"expanded-ch1"}]},{"id":"c6-tiles","type":"tiles","tier":2,"title":"Education ↔ Plain English","targets":["1.6"],"status":"draft","instructions":"Build the complete explanation from the tiles.","items":[{"id":"E1-C6-TI-1","title":"Explain Telos and rigor 1","prompt":"Complete the explanation.","correct":["Rigor is cognitive demand connected to purpose","not simply the amount of work assigned"],"wrong":["Rigor is maximum workload","so purpose and judgment do not matter"],"why":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C6-TI-2","title":"Explain Telos and rigor 2","prompt":"Complete the explanation.","correct":["Rigor is cognitive demand connected to purpose","not simply the amount of work assigned"],"wrong":["Rigor is maximum workload","so purpose and judgment do not matter"],"why":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"},{"id":"E1-C6-TI-3","title":"Explain Telos and rigor 3","prompt":"Complete the explanation.","correct":["Rigor is cognitive demand connected to purpose","not simply the amount of work assigned"],"wrong":["Rigor is maximum workload","so purpose and judgment do not matter"],"why":"Telos is the purpose a thing is for; rigor is meaningful cognitive demand, not volume, pace, or busywork.","hint":"Choose the two statements that preserve the concept’s meaning.","_v":"chapter1-tier2"}]},{"id":"c6-apstyle","type":"choice","tier":3,"title":"AP-style review","targets":["1.6"],"status":"draft","items":[{"id":"E1-C6-AP-1","prompt":"Why does the question “What is education for?” matter for assessment design?","options":["It determines which abilities and forms of growth count as success","It makes measurement impossible","It replaces content knowledge","It guarantees one correct philosophy"],"answer":0,"why":"A theory of purpose shapes the outcomes an educational system chooses to cultivate.","_v":"edcor1"},{"id":"E1-C6-AP-2","prompt":"A school rewards only short-term recall although it claims to develop independent thinkers. The problem is mainly:","options":["a mismatch between telos and practice","too much rigor","mastery learning","domain specificity"],"answer":0,"why":"The stated end and the actual incentives point in different directions.","_v":"edcor1"},{"id":"E1-C6-AP-3","prompt":"Which conclusion best follows from the chapter?","options":["Rigor is meaningful only when connected to what students are meant to become","Rigor means maximum workload","Purpose is irrelevant to teaching","All students must learn identically"],"answer":0,"why":"Challenge should serve an educational purpose rather than become an end in itself.","_v":"edcor1"},{"id":"E1-C6-AP-4","prompt":"A teacher calls a 12-page assignment more rigorous than a four-question transfer task solely because it is longer. What is the best critique?","options":["Length measures volume, not necessarily cognitive demand","Length always proves rigor","Transfer tasks cannot be rigorous","Rigor is impossible to compare"],"answer":0,"why":"The course defines rigor by the thinking demanded, not the amount of work.","_v":"expanded-ch1"},{"id":"E1-C6-AP-5","prompt":"Which student best demonstrates the course’s telos?","options":["A student whose judgment and response have been formed, not only a student who can recite terms","A student who memorizes without applying","A student who finishes fastest","A student who avoids difficult questions"],"answer":0,"why":"Person-formation and changed judgment are part of the educational purpose.","_v":"expanded-ch1"}]}]}],"readiness":{"streak":5,"items":[{"id":"E1-R01","prompt":"Which claim best captures why education should include both knowledge and higher-order reasoning?","options":["Reasoning is independent of content.","Domain knowledge gives reasoning something to work with.","Facts make analysis impossible.","Only recall can be assessed."],"answer":1,"why":"The chapter argues that meaningful reasoning depends on knowledge in a domain."},{"id":"E1-R02","prompt":"A teacher keeps a demanding goal but adds feedback and corrective practice. Which principle is this?","options":["Lowered expectations","Mastery learning","Rigor as workload","Avoidance of challenge"],"answer":1,"why":"Mastery learning keeps the target while varying time and support."},{"id":"E1-R03","prompt":"Which statement best distinguishes rigor from mere difficulty?","options":["Rigor is more homework.","Rigor is meaningful thinking connected to a purpose.","Rigor is a faster timer.","Rigor is a harder textbook."],"answer":1,"why":"Rigor concerns cognitive demand and purpose, not difficulty alone."},{"id":"E1-R04","prompt":"A learner improves after a challenge because feedback reveals what to change. This illustrates:","options":["Fragility","Antifragile development","A fixed ability","Lower expectations"],"answer":1,"why":"Antifragile development uses challenge and feedback to become stronger."},{"id":"E1-R05","prompt":"Why should high expectations be paired with instructional support?","options":["Support makes the goal less demanding.","Support gives students a path to reach the demanding goal.","Support replaces knowledge.","Support guarantees identical outcomes."],"answer":1,"why":"High expectations are meaningful when students receive instruction, feedback, and time."}]}};